package com.codearena.common.api; import java.time.Instant; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { record Error(String code,String message,Instant timestamp){} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Error> validation(){return ResponseEntity.badRequest().body(new Error("VALIDATION_ERROR","Request validation failed",Instant.now()));} @ExceptionHandler(Exception.class) ResponseEntity<Error> fallback(Exception e){if(e instanceof org.springframework.web.server.ResponseStatusException x)return ResponseEntity.status(x.getStatusCode()).body(new Error("REQUEST_ERROR",x.getReason(),Instant.now()));return ResponseEntity.status(500).body(new Error("INTERNAL_ERROR","An unexpected error occurred",Instant.now()));} }
